select pos.CDATE, pos.PROD_ID, pos.CCY,pos.FEE_TYPE,sum(IFNULL(pos.AMT,0)) amt from CHB_PRD_FEE_POSITION pos inner join (select max(CDATE) cdate,prod_id from CHB_PRD_FEE_POSITION group by prod_id) a on a.prod_id=pos.prod_id and a.CDATE=pos.CDATE where pos.FEE_TYPE = '01'
#{item.prodId,jdbcType=VARCHAR}
group by pos.CDATE, pos.PROD_ID, pos.CCY,pos.FEE_TYPE
